pe": "topic", "title": "Periodization, Load Management, Peaking, and Return-to-Performance", "description": "Organize training across time while balancing performance, recovery, competition, and injury risk.", "children": [{"id": "c9672b6e-f612-4dc5-9cb1-0dac0e26372d", "type": "subtopic", "title": "Periodization models", "description": "Students compare ways to organize training across months and seasons.", "children": [{"id": "4d99def1-51fc-4dc9-b0fa-4603b015a58e", "type": "concept", "title": "Linear, undulating, block, conjugate, and agile periodization"}, {"id": "cd08c11d-2ba2-48c7-8738-c9ff7ac33546", "type": "concept", "title": "Preparation, competition, transition, and off-season phases"}, {"id": "f072cfed-876c-4ccf-b932-a1e4c58d691d", "type": "concept", "title": "Mesocycles, microcycles, and tapering"}]}, {"id": "d02a022c-afb0-468c-b66f-b2b570a8d859", "type": "subtopic", "title": "Load management", "description": "The goal is to balance performance improvement with fatigue and injury risk.", "children": [{"id": "1fb3bce1-b2e5-41c4-819f-9f7a0082e5df", "type": "concept", "title": "Internal and external load"}, {"id": "20eda82e-a00f-4250-9c0c-08fc38c76943", "type": "concept", "title": "Acute:chronic workload concepts and limitations"}, {"id": "3025e2af-1f22-4f3b-b8cd-92195244f710", "type": "concept", "title": "Deloading, monotony, strain, and recovery planning"}]}, {"id": "bea41eeb-cbbe-439c-91e4-0ef162e509cb", "type": "subtopic", "title": "Peaking and return-to-performance", "description": "Learners apply periodization to key competitions and re-entry after injury.", "children": [{"id": "c952cbfa-7db8-4569-bd4f-5383895ac5fa", "type": "concept", "title": "Tapering and freshness"}, {"id": "39f50314-3eab-4629-9c54-4bfa7656f7f7", "type": "concept", "title": "Return-to-train, return-to-practice, and return-to-compete progressions"}, {"id": "15f9f022-f4b3-44c7-87b2-cbb0f760528f", "type": "concept", "title": "Communication with clinicians, coaches, and athletes"}]}]}, {"id": "e156c844-b5bc-48f2-adb2-3b211e9876cc", "type": "topic", "title": "Athlete Monitoring, Testing Data, Technology, and Evidence-Based Decisions", "description": "Use data and research responsibly to adjust training and communicate performance decisions.", "children": [{"id": "81536951-0353-4b22-a73c-3db69c7de7f8", "type": "subtopic", "title": "Monitoring tools", "description": "Students learn what to measure and why.", "children": [{"id": "df85a024-7085-431e-80e7-01c139b06d6c", "type": "concept", "title": "Wellness questionnaires, RPE, session load, heart rate, HRV, jump tests, velocity, GPS, and force plates"}, {"id": "d9c346e0-1b44-4aee-8261-afc7f0a9ba42", "type": "concept", "title": "Data quality, noise, minimal detectable change, and interpretation"}, {"id": "4c64e8df-b073-44ee-b620-cb26e76821b3", "type": "concept", "title": "Cost, feasibility, privacy, and compliance"}]}, {"id": "6aebabb9-7bc3-434c-8bb5-440440a0ffb5", "type": "subtopic", "title": "Data-informed coaching", "description": "This subtopic teaches students to use data as decision support, not a replacement for judgment.", "children": [{"id": "d68ffcfa-7c5b-4b17-92a1-1b109466e10b", "type": "concept", "title": "Dashboards and trend interpretation"}, {"id": "e3ff5ca7-2d49-454f-88d6-5be954772283", "type": "concept", "title": "Flagging fatigue, readiness, and adaptation"}, {"id": "07f79d78-9fa3-4681-9dde-c833c503f91b", "type": "concept", "title": "Communicating findings to athletes and coaches"}]}, {"id": "68056307-1931-4a89-8df5-e4fcd0271947", "type": "subtopic", "title": "Evidence-based practice", "description": "Learners practice reading research and applying it without overclaiming.", "children": [{"id": "b68167f6-990f-44a6-89d7-0c2f609de993", "type": "concept", "title": "Study designs, effect sizes, and practical significance"}, {"id": "7d208780-525e-4f30-b103-0ed2d2a12873", "type": "concept", "title": "Population specificity and transfer to the field"}, {"id": "d4ca077e-9ca5-49c9-a1a0-9fecd03482bb", "type": "concept", "title": "Misinformation, social media claims, and continuing education"}]}]}, {"id": "d91dbf78-4cd4-4007-80d7-d5ee665c3e31", "type": "topic", "title": "Special Populations, Ethics, Communication, and Applied Coaching Capstone", "description": "Adapt programs for diverse clients and synthesize the course through a professional coaching plan.", "children": [{"id": "13e16fa1-114c-48c1-8bb7-c1a3a6774bae", "type": "subtopic", "title": "Adapting training", "description": "Students learn to modify programs for people with different goals, bodies, ages, and constraints.", "children": [{"id": "4628979b-3f15-48b0-9fa0-8bab22912d90", "type": "concept", "title": "Youth, older adults, novice trainees, tactical athletes, pregnant and postpartum clients, and athletes with disabilities"}, {"id": "72549eff-450b-42a1-9c53-78742dd36ad5", "type": "concept", "title": "Chronic disease, pain, injury history, and referral boundaries"}, {"id": "e9438490-1665-489b-9dbe-f89edd9010c5", "type": "concept", "title": "Inclusive language, accessibility, and individual preference"}]}, {"id": "93eb2c7f-7912-4bf1-a635-a0ab2ac1a8ab", "type": "subtopic", "title": "Professional communication", "description": "The gist is that coaching success depends on relationships as much as program design.", "children": [{"id": "18a5d806-2f1d-44ab-a678-2a486adeed75", "type": "concept", "title": "Motivational interviewing basics"}, {"id": "8e731fe3-228c-4d85-8fef-c9860b9a4544", "type": "concept", "title": "Feedback, difficult conversations, and behavior change"}, {"id": "cbe535a0-4fdd-4051-a332-d8bc1d435dc2", "type": "concept", "title": "Documentation, reports, and stakeholder communication"}]}, {"id": "caaf9178-7a59-4e48-9d62-88270938ca15", "type": "subtopic", "title": "Applied capstone", "description": "Learners synthesize the course into a complete coaching product.", "children": [{"id": "d224cd4b-e7a5-4e78-9786-d9dfa7e7efaa", "type": "concept", "title": "Needs analysis and assessment plan"}, {"id": "53781365-529a-4420-b6b7-d18a84d81902", "type": "concept", "title": "Training program, monitoring plan, and progression rationale"}, {"id": "732d4cdf-0555-42ab-bb94-7e0cabb84c74", "type": "concept", "title": "Coaching demonstration, reflection, and professional development plan"}]}]}], "dbBacked": true}$sacjson$::jsonb,
