  summary = 'Designed as a 15-module upper-division course. Each module can map to one week in a semester format, with coaching labs, technique demonstrations, assessment practice, program-design workshops, monitoring-data exercises, and a final applied training plan.',
  data = $sacjson${"slug": "strength-and-conditioning", "title": "Strength and Conditioning", "description": "Designed as a 15-module upper-division course. Each module can map to one week in a semester format, with coaching labs, technique demonstrations, assessment practice, program-design workshops, monitoring-data exercises, and a final applied training plan.", "topics": [{"id": "31996dbc-02cd-4530-bfd4-3c3942ae27e4", "type": "topic", "title": "Strength and Conditioning Profession, Safety, and Coaching Framework", "description": "Orient students to the field, professional roles, safety expectations, and evidence-informed coaching practice.", "children": [{"id": "5104616c-8f4f-47e1-bbac-c4ea1d1a404b", "type": "subtopic", "title": "Professional scope and roles", "description": "Students learn what strength and conditioning professionals do, where they work, and when referral is necessary.", "children": [{"id": "07c2abb8-4f86-4a7a-9d79-ad7650a38209", "type": "concept", "title": "Sport performance, tactical, fitness, wellness, and return-to-performance settings"}, {"id": "31a4fcd8-64a9-4740-9a52-c9b9e745cc4f", "type": "concept", "title": "CSCS, CPT, exercise physiologist, coach, and allied health boundaries"}, {"id": "bb92ea77-5cf1-424f-b90d-e124ea58cb5a", "type": "concept", "title": "Interprofessional collaboration with athletic trainers, clinicians, dietitians, and sport coaches"}]}, {"id": "f7af77b4-558e-4cae-bde7-e76415b571bb", "type": "subtopic", "title": "Safety and risk management", "description": "The goal is to make safety a design principle, not an afterthought.", "children": [{"id": "cb57616a-29ef-45d9-bd27-e5e9c2066c2c", "type": "concept", "title": "Facility layout, equipment inspection, spotting, and emergency procedures"}, {"id": "f67be3e8-a7cf-41ed-ac8c-cb6049c14ee4", "type": "concept", "title": "Informed consent, screening, supervision ratios, and documentation"}, {"id": "8f3b681c-bddb-4f6f-8f81-074cf8d5be70", "type": "concept", "title": "Heat, hydration, exertional illness, and environmental risk"}]}, {"id": "e027ed53-a8d2-4227-bf4e-0ac86ee59faf", "type": "subtopic", "title": "Coaching philosophy", "description": "Learners build a practical model for coaching behavior and decision-making.", "children": [{"id": "644cd095-a48d-400b-8a03-f9300ac6cfb2", "type": "concept", "title": "Evidence-informed practice and athlete-centered coaching"}, {"id": "f3ad4a5d-b2df-4ff1-8d48-3253dec7b568", "type": "concept", "title": "Communication, cueing, feedback, and trust"}, {"id": "4492f5fa-3da8-4a9e-af67-eb00798080d8", "type": "concept", "title": "Ethics, professionalism, inclusion, and long-term development"}]}]}, {"id": "e3f4da3f-23c1-423a-846a-e69362c90980", "type": "topic", "title": "Exercise Physiology, Adaptation, and Training Theory", "description": "Explain how stress, recovery, specificity, and overload drive adaptation across fitness and performance goals.", "children": [{"id": "b9ae5b9f-c9e1-4979-b042-0577b73929fe", "type": "subtopic", "title": "Stress, recovery, and adaptation", "description": "Students learn how training stress becomes useful only when recovery permits adaptation.", "children": [{"id": "d924caa6-1f97-469f-937f-024aba6436e6", "type": "concept", "title": "General adaptation concepts"}, {"id": "aa8223dc-d9f7-4963-a911-bb10dcf63809", "type": "concept", "title": "Fitness-fatigue and stimulus-recovery-adaptation models"}, {"id": "1919d853-35b8-41c4-96ca-1f9cbdb1ce3b", "type": "concept", "title": "Overload, specificity, progression, variation, reversibility, and individuality"}]}, {"id": "34589793-fd2d-4c07-a776-59b4857bef34", "type": "subtopic", "title": "Neuromuscular and metabolic foundations", "description": "This subtopic connects program variables to the systems they challenge.", "children": [{"id": "ab5a0bb8-1644-4177-adcc-e2a13bf818f2", "type": "concept", "title": "Motor units, recruitment, rate coding, synchronization, and coordination"}, {"id": "7a232dcb-e458-4e55-bd4f-25a89c10b5d0", "type": "concept", "title": "ATP-PC, glycolytic, and oxidative energy systems"}, {"id": "cd93ee6d-9e98-497c-a464-b7e6428a50cc", "type": "concept", "title": "Muscle fiber types, hypertrophy, tendon adaptation, and connective tissue response"}]}, {"id": "9af283c2-ea54-4c76-8e0f-baf028185aa3", "type": "subtopic", "title": "Training status and context", "description": "Learners understand why the same program can be too easy, productive, or harmful depending on the person.", "children": [{"id": "27335f84-bab6-43dc-af34-03fb420bd1d4", "type": "concept", "title": "Novice, intermediate, advanced, youth, adult, and older adult trainees"}, {"id": "63f49910-6674-4ffa-92f0-f01be7c794ce", "type": "concept", "title": "Sport season, competition calendar, health status, and training age"}, {"id": "1cce6719-a033-42a0-911a-0e58fbaed096", "type": "concept", "title": "Lifestyle stress, sleep, nutrition, readiness, and recovery resources"}]}]}, {"id": "e79a767d-8f57-455b-9790-28db9500f625", "type": "topic", "title": "Biomechanics, Movement Analysis, and Exercise Technique Foundations", "description": "Use mechanical principles to coach movement quality, loading, and efficient force production.", "children": [{"id": "1467f5cf-ccf4-4b52-be05-197db1901031", "type": "subtopic", "title": "Force, motion, and loading", "description": "Students use mechanics to explain what exercises demand from joints and tissues.", "children": [{"id": "a20f6180-db6f-41d5-a891-b4847aedc5e3", "type": "concept", "title": "Newton's laws, force, torque, impulse, work, energy, and power"}, {"id": "c394a292-ddbd-4176-93d1-250aaefc6f85", "type": "concept", "title": "Moment arms, center of mass, base of support, and stability"}, {"id": "d205205d-76a5-49b2-90e1-1e940e94438e", "type": "concept", "title": "Joint loading, tissue tolerance, and exercise constraints"}]}, {"id": "16729443-5548-4a6d-9a0c-7ffcb93ed392", "type": "subtopic", "title": "Movement analysis", "description": "The point is to observe movement systematically before coaching or correcting it.", "children": [{"id": "9994783d-d02b-4284-b39a-2d64a1e4a092", "type": "concept", "title": "Planes and axes of motion"}, {"id": "3145f487-bcc9-4107-82ee-a0f1a98119fd", "type": "concept", "title": "Squat, hinge, lunge, push, pull, carry, jump, sprint, and throw patterns"}, {"id": "943741d7-26a2-4eaa-9beb-858e8748d049", "type": "concept", "title": "Video analysis, qualitative observation, and common technique errors"}]}, {"id": "bf93d323-5a67-455f-9d19-03b25a81c80f", "type": "subtopic", "title": "Technique coaching foundations", "description": "Learners connect mechanics to practical cues and regressions.", "children": [{"id": "20e9bbe2-35e4-4c14-a8da-e8f36ba194b0", "type": "concept", "title": "External versus internal cues"}, {"id": "cce4efaf-ea0c-4530-b385-073fffd5cbf0", "type": "concept", "title": "Set-up, bracing, tempo, range of motion, and intent"}, {"id": "b9dd862e-fc7c-4523-b1c6-8914e51b5d40", "type": "concept", "title": "Regression, progression, constraint, and individual anatomy"}]}]}, {"id": "27e9e353-e4d4-460e-b463-e5102139bc21", "type": "topic", "title": "Assessment, Screening, Needs Analysis, and Goal Setting", "description": "Translate athlete or client information into training priorities, baselines, and measurable goals.", "children": [{"id": "647192af-e1e8-4952-8b79-92de7b6c9c31", "type": "subtopic", "title": "Preparticipation screening", "description": "Students learn to decide whether training, modification, or referral is appropriate.", "children": [{"id": "6618068b-5b57-4495-bdf2-518d057ed4b5", "type": "concept", "title": "Health history, PAR-Q style tools, contraindications, and red flags"}, {"id": "f67163bf-7127-46a5-ad05-566d3ec73828", "type": "concept", "title": "Risk stratification and emergency planning"}, {"id": "0b7af693-df69-443a-85a0-817475fece94", "type": "concept", "title": "Scope of practice and documentation"}]}, {"id": "51ad479c-3ce3-43b4-8fbd-a7c5b9853e79", "type": "subtopic", "title": "Performance an