f force development"}, {"id": "f6abce62-348b-4851-be71-dfc10208b9b0", "type": "concept", "title": "Force-velocity relationship"}, {"id": "154feca2-94e4-4556-b4af-bad0cd3357e0", "type": "concept", "title": "Impulse, intent, and movement speed"}]}, {"id": "48170847-33a4-4182-b13d-36b4ae5bfb1f", "type": "subtopic", "title": "Olympic-lift derivatives", "description": "The point is to use weightlifting derivatives where they fit, with appropriate technical progressions.", "children": [{"id": "637f9f3e-bb00-46b7-93d4-c661644cc1b7", "type": "concept", "title": "Pulls, high pulls, power cleans, power snatches, and catch-free variations"}, {"id": "75817045-06e8-4ac1-97de-475167cdf266", "type": "concept", "title": "Teaching progressions and common errors"}, {"id": "69a9d9e1-b7a5-48da-8282-1ae7d49bc1b5", "type": "concept", "title": "Load selection and safety considerations"}]}, {"id": "a21922da-27d5-4893-9e8b-8ae540b1d7cc", "type": "subtopic", "title": "Ballistic and loaded power methods", "description": "Learners compare power tools beyond weightlifting.", "children": [{"id": "5dfc0032-88c7-4e01-afda-33238afd004a", "type": "concept", "title": "Jump squats, trap-bar jumps, medicine balls, throws, kettlebells, sleds, and bands"}, {"id": "c644bab9-9320-4cf6-97f7-d74567a0d730", "type": "concept", "title": "Load-power profiling basics"}, {"id": "bdcbcd15-8d47-42fb-a428-4761404826c2", "type": "concept", "title": "Contrast, complex, and potentiation methods"}]}]}, {"id": "66556d2f-90f8-4114-9858-6d4bc86c4303", "type": "topic", "title": "Plyometric Training, Landing Mechanics, and Reactive Ability", "description": "Build elastic, reactive, and deceleration qualities while managing tissue stress and technique.", "children": [{"id": "ae21727e-e384-4ce6-bae2-b5b650badc74", "type": "subtopic", "title": "Plyometric foundations", "description": "Students learn the stretch-shortening cycle and why plyometrics need prerequisites.", "children": [{"id": "e3eb878c-0322-45a0-ac93-0913e098825e", 